setlocal
set "BASE=C:\Users\Administrator\.codex"
set "INDEX=%BASE%\session_index.jsonl"
set "SESSIONS=%BASE%\sessions"

type nul &gt; "%INDEX%"

if exist "%SESSIONS%" (
    for /f "delims=" %%I in ('dir /b /a "%SESSIONS%" 2^&gt;nul') do (
        if exist "%SESSIONS%\%%I\" (
